import { act, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener() {}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() { return { theme: "light" }; }
		async openLink() { return { isError: false }; }
	},
	PostMessageTransport: class { async close() {} },
}));

describe("review race", () => {
	beforeEach(() => {
		vi.resetModules();
		bridge.listeners.clear();
		bridge.callServerTool.mockReset();
		bridge.callServerTool.mockImplementation(async ({ name }: { name: string }) =>
			name === "restore_lobu_app_result"
				? { structuredContent: { found: true, tool_name: "query_sql", data: { title: "Restored B" }, view_state: {} } }
				: { structuredContent: { saved: true } },
		);
	});

	it("does not let delayed widget cache replace a capability restore", async () => {
		const parent = Object.assign(new EventTarget(), { location: { origin: window.location.origin } });
		Object.defineProperty(window, "parent", { configurable: true, value: parent });
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title ?? "none"}</span>;
		}
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalled());
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? [])
				handler({ structuredContent: { title: "Live A" } });
		});
		expect(await screen.findByText("Live A")).toBeInTheDocument();
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? [])
				handler({ structuredContent: {}, _meta: { "lobu/mcp-app-snapshot-capability": "token-b" } });
		});
		expect(await screen.findByText("Restored B")).toBeInTheDocument();
		act(() => {
			parent.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: {
				widgetState: { privateContent: { lobuViewSnapshot: { version: 1, data: { title: "Stale A" } } } },
			} } }));
		});
		expect(screen.queryByText("Stale A")).not.toBeInTheDocument();
		expect(screen.getByText("Restored B")).toBeInTheDocument();
	});
});

