import { act, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
const bridge = vi.hoisted(() => ({ callServerTool: vi.fn(), connect: vi.fn().mockResolvedValue(undefined), hostContext: {} as Record<string, unknown>, listeners: new Map<string, Set<(p: unknown) => void>>() }));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(n: string, h: (p: unknown) => void) { const s=bridge.listeners.get(n)??new Set(); s.add(h); bridge.listeners.set(n,s); }
		removeEventListener() {}
		callServerTool=bridge.callServerTool; connect=bridge.connect;
		getHostContext(){ return { theme:"light", ...bridge.hostContext }; }
		async openLink(){return {isError:false};}
	},
	PostMessageTransport: class { async close(){} },
}));
describe("clear boundary",()=>{
	beforeEach(()=>{vi.resetModules(); bridge.listeners.clear(); bridge.callServerTool.mockReset().mockResolvedValue({structuredContent:{saved:true}}); bridge.hostContext={toolInfo:{id:"old-card",tool:{name:"query_sdk"}}};});
	it("does not save a post-clear result against the prior card",async()=>{
		const parent=Object.assign(new EventTarget(),{location:{origin:window.location.origin}}); Object.defineProperty(window,"parent",{configurable:true,value:parent});
		const {Provider,useMcpApp}=await import("./host");
		function Probe(){const {data,setViewState}=useMcpApp<{title:string}>();return <><span>{data?.title??"none"}</span><button type="button" onClick={()=>setViewState("details.open",true)}>edit</button></>}
		render(<Provider devMock={{title:"dev"}}><Probe/></Provider>); await waitFor(()=>expect(bridge.connect).toHaveBeenCalled());
		act(()=>{for(const h of bridge.listeners.get("toolresult")??[])h({structuredContent:{title:"Old"}})}); expect(await screen.findByText("Old")).toBeInTheDocument();
		act(()=>parent.dispatchEvent(new CustomEvent("openai:set_globals",{detail:{globals:{toolOutput:null}}}))); expect(await screen.findByText("none")).toBeInTheDocument();
		act(()=>parent.dispatchEvent(new CustomEvent("openai:set_globals",{detail:{globals:{toolOutput:{title:"New"}}}}))); expect(await screen.findByText("New")).toBeInTheDocument();
		bridge.callServerTool.mockClear(); fireEvent.click(screen.getByRole("button",{name:"edit"}));
		await new Promise(r=>setTimeout(r,300));
		expect(bridge.callServerTool).not.toHaveBeenCalledWith(expect.objectContaining({name:"save_lobu_app_state",arguments:expect.objectContaining({tool_call_id:"old-card"})}));
	});
});

